<feComponentTransfer in="raw" result="bin"><feFuncR type="linear" slope="60"/><feFuncG type="linear" slope="60"/><feFuncB type="linear" slope="60"/><feFuncA type="linear" slope="0" intercept="1"/></feComponentTransfer>
