const rawPath=(pts,cls,col,w,op,extra='')=>`<path ${cls?`class="${cls}" `:''}${extra}d="${pts.map((q,i)=>(i?'L':'M')+f1(q[0])+','+f1(q[1])).join('')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round" opacity="${op}"/>`;
